# Approximate Suricata buffer semantics in Python to sanity-check the rule's pcre/content parts.
import json, re, sys, os, glob
sys.path.insert(0, 'out/suricata-http-exfil-rule/scripts')
import pcaplib
d = json.load(open(sys.argv[1])); rule = d['rule_text']
# split rule into buffer -> [(kind, val)]
opts = re.findall(r'(\w[\w.]*)(?::"((?:[^"\\]|\\.)*)"|:([^;]*))?;', rule[rule.index('(')+1:])
bufs = {}; cur = None
for k, q, v in opts:
    if k in ('http.method','http.uri','http.header','http.request_body'): cur = k; bufs.setdefault(k, []); continue
    if cur and k in ('content','pcre','bsize','startswith','nocase'): bufs[cur].append((k, q or v))
def check(buf, items):
    last = None
    for k, v in items:
        if k == 'content':
            lit = re.sub(r'\|([0-9a-f ]+)\|', lambda m: bytes.fromhex(m.group(1)).decode('latin-1'), v); last = lit
            if lit not in buf: 
                if not (any(x[0]=='nocase' for x in items) and lit.lower() in buf.lower()): return False
        elif k == 'bsize' and len(buf) != int(v): return False
        elif k == 'startswith' and not buf.startswith(last): return False
        elif k == 'pcre':
            body, flags = v[1:v.rindex('/')], v[v.rindex('/')+1:]
            if not re.search(body, buf, re.I if 'i' in flags else 0): return False
    return True
w = d['workdir']; ok = 0; bad = []
for c in d['checks']:
    path = c['name'] if c['kind']=='labeled' else glob.glob(f"{w}/mut-*-{re.sub(r'[^A-Za-z0-9_.-]','_',c['name'])}.pcap")[0]
    if c['kind']=='labeled': path = os.path.join(sys.argv[2], path)
    hit = False
    for s in pcaplib.client_streams(path):
        for r in pcaplib.parse_requests(s['data']):
            b = {'http.method': r['method'], 'http.uri': r['uri'],
                 'http.header': ''.join(f"{n}: {v}\r\n" for n, v in r['headers']), 'http.request_body': r['body']}
            hit |= all(check(b[k], it) for k, it in bufs.items())
    (bad.append(c['name']) if hit != c['expect_alert'] else None); ok += hit == c['expect_alert']
print('regex-level agreement', ok, '/', len(d['checks']), 'mismatches:', bad)
EOF
